def make(i, row):
    tag, prompt, opts, answer, reason = row
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = next(o['id'] for o in options if o['text'] == answer)
    refs = [{'url': u, 'title': t + '；僅研究題型與能力方向，未複製原題。', 'year': '113-114', 'subject': 'social', 'locator': loc, 'observedPattern': '公開社會科產業與貿易資料題研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'} for u, t, loc in SOURCES]
    steps = [f'讀題定位：圈出「{tag}」與題目給的市場、產品、期間、分母或利益條件。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合新興市場與臺灣產業關聯的資料判讀。', '排除誘答：檢查是否把總量當比重、單一案例當全體，或忽略成本、風險與外部影響。', '結論回查：確認資料範圍、產品分類與推論強度相配，不做超出證據的外推。']
    return {'id': f'question-social-content-geo-be-iv-4-{i}', 'subject': 'social', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-social-content-geo-be-iv-4'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': SOURCES[0][0], 'sourceLocator': '公立國中社會科公開試題；研究新興市場、臺灣產業、全球供應鏈與資料界線的能力方向。', 'authoringNote': '依官方課綱 KG 與三個公立學校公開來源的題型／能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-09', 'lessonId': 'lesson-social-content-geo-be-iv-4', 'examPatternRefs': refs, 'solutionStrategy': '先釐清市場、產品與供應鏈的資料範圍，再比較分母、時間、風險與產業外部影響。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-social-content-geo-be-iv-4-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
